"use client";

import * as React from "react";
import styles from "../styles/shimmer-text.module.css";

export interface ShimmerTextProps {
  /** Text the highlight sweeps across */
  text?: string;
  /** Duration of one sweep in seconds */
  duration?: number;
  /** Resting text color */
  baseColor?: string;
  /** Color of the moving highlight */
  shimmerColor?: string;
  /** Optional className */
  className?: string;
}

export function ShimmerText({
  text = "Generating your preview...",
  duration = 2.5,
  baseColor = "#71717a",
  shimmerColor = "#f4f4f6",
  className = "",
}: ShimmerTextProps) {
  const styleVars = {
    "--mf-sh-duration": `${duration}s`,
    "--mf-sh-base": baseColor,
    "--mf-sh-shine": shimmerColor,
  } as React.CSSProperties;

  return (
    <span style={styleVars} className={`${styles.root} ${className}`.trim()}>
      {text}
    </span>
  );
}

.root {
  display: inline-block;
  font-size: 1.125rem;
  font-weight: 500;
  letter-spacing: -0.01em;
  color: var(--mf-sh-base, var(--mf-subtle, #71717a));
  background-image: linear-gradient(
    110deg,
    var(--mf-sh-base, var(--mf-subtle, #71717a)) 35%,
    var(--mf-sh-shine, var(--mf-fg, #f4f4f6)) 50%,
    var(--mf-sh-base, var(--mf-subtle, #71717a)) 65%
  );
  background-size: 250% 100%;
  background-position: 100% 0;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: mf-sh-sweep var(--mf-sh-duration, 2.5s) linear infinite;
}

@keyframes mf-sh-sweep {
  from {
    background-position: 100% 0;
  }
  to {
    background-position: -150% 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .root {
    animation: none;
    background-image: none;
    -webkit-text-fill-color: currentColor;
  }
}

