"use client";

import { motion } from "motion/react";

export function ShimmerTextTailwind({ text = "Generating your preview..." }) {
  return (
    <motion.span
      className="inline-block bg-[linear-gradient(110deg,#71717a_35%,#f4f4f6_50%,#71717a_65%)] bg-[length:250%_100%] bg-clip-text text-lg font-medium text-transparent"
      animate={{ backgroundPosition: ["100% 0%", "-150% 0%"] }}
      transition={{ duration: 2.5, repeat: Infinity, ease: "linear" }}
    >
      {text}
    </motion.span>
  );
}
